{"command":"python3 << 'EOF'
with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

# Check required sections
sections = ['# Overview', '# Input data', '# Methods', '# Generated outputs', '# Main results', '# Limitations', '# Reproducibility']

for section in sections:
    if section in content:
        # Find section content
        idx = content.find(section)
        next_section_idx = float('inf')
        for s in sections:
            if s != section:
                s_idx = content.find(s, idx + 1)
                if s_idx > 0 and s_idx < next_section_idx:
                    next_section_idx = s_idx

        section_content = content[idx:next_section_idx] if next_section_idx != float('inf') else content[idx:]
        # Count sentences (roughly by periods)
        sentences = [s.strip() for s in section_content.split('\n') if len(s.strip()) > 0]
        text_length = len(section_content.replace(section, '').strip())
        print(f"{section}: {len(sentences)} lines, {text_length} chars (excluding header)")
    else:
        print(f"{section}: NOT FOUND!")

# Check for references to outputs/
if 'outputs/' in content:
    print("\nReferences to outputs/ found: YES")
else:
    print("\nReferences to outputs/ found: NO")

# Check for live API claims
if 'live API' in content.lower() or 'api access' in content.lower():
    print("Contains live API claims: YES (PROBLEM)")
else:
    print("Contains live API claims: NO (OK)")
EOF"}

